window.formatUsd = function formatUsd(n) {
  return "$" + Number(n).toFixed(2);
};

window.formatCny = function formatCny(n) {
  if (n == null || n === "") return "";
  return "¥" + Number(n).toFixed(2);
};

window.escapeHtml = function escapeHtml(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
};

window.getSiteBase = function getSiteBase() {
  if (typeof window.SITE_BASE === "string" && window.SITE_BASE) {
    return window.SITE_BASE.endsWith("/") ? window.SITE_BASE : window.SITE_BASE + "/";
  }
  // Fallback: resolve against /finds or current file so Live Server parent-root works
  const href = location.href;
  if (/\/finds\/?(\?|$)/.test(location.pathname) || /\/finds\//.test(location.pathname)) {
    let base = new URL("../", href).pathname;
    if (!base.endsWith("/")) base += "/";
    return base;
  }
  let base = new URL("./", href).pathname;
  if (/\.[a-z0-9]+$/i.test(base)) base = base.replace(/\/[^/]+$/, "/");
  if (!base.endsWith("/")) base += "/";
  return base;
};

window.itemPath = function itemPath(id, base) {
  const prefix = base != null ? base : window.getSiteBase();
  return prefix + "item.html?id=" + encodeURIComponent(id);
};

window.productCardHtml = function productCardHtml(p, detailsHref) {
  const href = detailsHref || window.itemPath(p.id);
  const title = window.escapeHtml(p.title);
  return (
    '<article class="product-card">' +
      '<div class="product-media">' +
        '<a href="' + href + '">' +
          '<img src="' + p.image + '" alt="' + title + ' — Kakobuyspreadsheet" loading="lazy" />' +
        "</a>" +
        '<button class="fav-btn" type="button" aria-label="Save ' + title + '" data-fav="' + p.id + '">' +
          '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 21s-6.5-4.2-9-8.2C1.2 9.5 2.4 6 5.6 5.2 7.6 4.7 9.5 5.5 12 8c2.5-2.5 4.4-3.3 6.4-2.8 3.2.8 4.4 4.3 2.6 7.6C18.5 16.8 12 21 12 21z"/></svg>' +
        "</button>" +
      "</div>" +
      '<div class="product-body">' +
        '<span class="product-cat">' + window.escapeHtml(p.categoryLabel) + "</span>" +
        '<h3 class="product-title"><a href="' + href + '">' + title + "</a></h3>" +
        '<p class="product-price">' + window.formatUsd(p.usd) + "</p>" +
        '<div class="product-actions">' +
          '<a class="btn btn-ghost" href="' + href + '">View details</a>' +
          '<a class="btn btn-solid" href="' + p.kakobuy + '" target="_blank" rel="noopener">Buy →</a>' +
        "</div>" +
      "</div>" +
    "</article>"
  );
};
